DROP TABLE IF EXISTS `novel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `novel` (
  `nIndex` int unsigned NOT NULL,
  `Title` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `Category` char(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `State` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `Love` int unsigned NOT NULL,
  `Series` int DEFAULT NULL,
  `SeriesN` int DEFAULT NULL,
  `Warrant` char(15) DEFAULT NULL,
  `Link` varchar(40) NOT NULL,
  `Introduction` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `aIndex` int unsigned DEFAULT NULL,
  `pIndex` int unsigned DEFAULT NULL,
  PRIMARY KEY (`nIndex`),
  UNIQUE KEY `nIndex_UNIQUE` (`nIndex`),
  KEY `fk_novel_publish` (`pIndex`),
  KEY `fk_novel_author` (`aIndex`),
  CONSTRAINT `fk_novel_author` FOREIGN KEY (`aIndex`) REFERENCES `author` (`aIndex`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_novel_publish` FOREIGN KEY (`pIndex`) REFERENCES `publish` (`pIndex`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
